// Demo: Signature FIDO2 Security Keys — challenge-response flow
function sign(ch,sk){var h=0;var s=ch+sk;for(var i=0;i<s.length;i++){h=(h*33+s.charCodeAt(i))>>>0;}return h.toString(16);}
var challenge='ch-1-2';
console.log('technique: Signature FIDO2 Security Keys');console.log('challenge: '+challenge);
console.log('response: '+sign(challenge,'device-key'));
console.log('server verifies with the registered public key — no shared secret on the wire');

